///\n\n@use 'config/colors';\n@use 'config/fonts';\n@use 'functions/color';\n@use 'mixins/aria';\n@use 'mixins/font';\n@use 'mixins/position';\n@use 'mixins/spacing';\n@use 'mixins/transition';\n\n.container {\n  position: relative;\n  @include spacing.padding-xy($x: 35px, $y: 12px);\n  @include font.apply(fonts.$primary, ( font-weight: 300 ));\n  font-size: 14px;\n  color: colors.$transparent;\n  letter-spacing: 3px;\n  text-align: center;\n  text-transform: uppercase;\n  background: linear-gradient(75deg, #4A9AC7 5%, #F148CC 95%) 0 0 / 200% 100%;\n  background-clip: text;\n  border-radius: 100px;\n  @include transition.apply(color, box-shadow);\n\n  &.light {\n    box-shadow: (\n      0 0 1px color.alpha(colors.$black, 0.4),\n      0 0 4px color.alpha(colors.$gray-dark, 0.24),\n    );\n\n    &.mina {\n      box-shadow: (\n        0 0 1px color.alpha(#770629, 0.4),\n        0 0 4px color.alpha(#D76D8E, 0.24),\n      );\n    }\n  }\n\n  &.dark {\n    box-shadow: (\n      0 0 1px color.alpha(colors.$white, 0.4),\n      0 0 12px color.alpha(colors.$black, 0.4),\n    );\n  }\n\n  &.mina {\n    background: linear-gradient(65deg, #E94489 2%, #F8C8C5 98%) 0 0 / 200% 100%;\n    background-clip: text;\n  }\n\n  &::before {\n    content: '';\n    @include position.absolute-fill;\n    background: linear-gradient(75deg, #4A9AC7 5%, #F148CC 95%) 0 0 / 200% 100%;\n    border-radius: 100px;\n    opacity: 0;\n    @include transition.apply((background-position, 1.5s), opacity);\n    z-index: -1;\n  }\n\n  &.mina::before {\n    background: linear-gradient(65deg, #E94489 2%, #F8C8C5 98%) 0 0 / 200% 100%;\n  }\n\n  @include aria.outline($radius: 100px);\n\n  &:hover {\n    color: colors.$white;\n    background-clip: border-box;\n\n    &::before {\n      background-position: 100% 0;\n      opacity: 0.65;\n    }\n\n    &.light::after {\n      @include aria.outline-hover;\n    }\n\n    &.dark::after {\n      @include aria.outline-hover($color: colors.$white);\n    }\n  }\n\n  &:focus {\n    &.light::after, &.dark::after {\n      @include aria.outline-show;\n    }\n  }\n\n  span, strong {\n    display: inline-block;\n  }\n\n  strong {\n    font-weight: 600;\n  }\n}\n","////\n/// @group spacing\n/// @access public\n/// @author Keith Choison <keith@tize.io>\n/// @since 0.1.0\n////\n\n@use 'functions/list';\n\n@mixin -spacing(\n  $prop,\n  $top: null,\n  $right: null,\n  $bottom: null,\n  $left: null,\n) {\n  @if not list.includes('margin' 'padding', $prop) {\n    @error 'Invalid $prop value passed to the -spacing() mixin: #{$prop}';\n  }\n\n  @if $top and $right and $bottom and $left { // all directions specified\n    @if $right == $left {\n      @if $top == $bottom {\n        @if $top == $right { // $top (== $bottom) == $right (== $left)\n          #{$prop}: $top;\n        } @else { // $top (== $bottom) != $right (== $left)\n          #{$prop}: $top $right;\n        }\n      } @else { // $top != $bottom, but $right == $left\n        #{$prop}: $top $right $bottom;\n      }\n    } @else { // $right != $left\n      #{$prop}: $top $right $bottom $left;\n    }\n  } @else { // not all directions specified\n    @if $top {\n      #{$prop}-top: $top;\n    }\n\n    @if $right {\n      #{$prop}-right: $right;\n    }\n\n    @if $bottom {\n      #{$prop}-bottom: $bottom;\n    }\n\n    @if $left {\n      #{$prop}-left: $left;\n    }\n  }\n}\n\n// margin\n\n@mixin margin(\n  $top: null,\n  $right: null,\n  $bottom: null,\n  $left: null,\n  $x: null,\n  $y: null,\n  $all: null,\n) {\n  @include -spacing(\n    $prop: margin,\n    $top: if($top, $top, if($y, $y, $all)),\n    $right: if($right, $right, if($x, $x, $all)),\n    $bottom: if($bottom, $bottom, if($y, $y, $all)),\n    $left: if($left, $left, if($x, $x, $all)),\n  );\n}\n\n///\n/// @alias margin()\n///\n@mixin m(\n  $a: null,\n  $x: null,\n  $y: null,\n  $t: null,\n  $r: null,\n  $b: null,\n  $l: null,\n) {\n  @include margin(\n    $all: $a,\n    $x: $x,\n    $y: $y,\n    $top: $t,\n    $right: $r,\n    $bottom: $b,\n    $left: $l,\n  );\n}\n\n@mixin margin-xy($x: null, $y: null) {\n  @include margin($x: $x, $y: $y);\n}\n\n///\n/// @alias margin-axis()\n///\n@mixin margin-axis($horizontal: null, $vertical: null) {\n  @include margin-xy($x: $horizontal, $y: $vertical);\n}\n\n@mixin margin-center {\n  @include margin($x: auto);\n}\n\n///\n/// @alias margin-center()\n///\n@mixin mx-auto {\n  @include margin-center;\n}\n\n@mixin margin-middle {\n  @include margin($y: auto);\n}\n\n///\n/// @alias margin-middle()\n///\n@mixin my-auto {\n  @include margin-middle;\n}\n\n@mixin margin-all($margin) {\n  @include margin($all: $margin);\n}\n\n///\n/// @alias margin-all()\n///\n@mixin margin-square($margin) {\n  @include margin-all($margin);\n}\n\n@mixin margin-auto {\n  @include margin-all(auto);\n}\n\n///\n/// @alias margin-auto()\n///\n@mixin m-auto {\n  @include margin-auto;\n}\n\n@mixin margin-none {\n  @include margin-all(0);\n}\n\n///\n/// @alias margin-none()\n///\n@mixin m-none {\n  @include margin-none;\n}\n\n///\n/// @alias m-none()\n///\n@mixin m-0 {\n  @include m-none;\n}\n\n@mixin margin-xy($x: null, $y: null) {\n  @include margin($x: $x, $y: $y);\n}\n\n///\n/// @alias margin-xy()\n///\n@mixin margin-axis($vertical: null, $horizontal: null) {\n  @include margin-xy($x: $horizontal, $y: $vertical);\n}\n\n@mixin margin-x($x: null) {\n  @include margin($x: $x);\n}\n\n///\n/// @alias margin-x()\n///\n@mixin mx($x: null) {\n  @include margin-x($x: $x);\n}\n\n@mixin mx-none {\n  @include mx($x: 0);\n}\n\n///\n/// @alias mx-none()\n///\n@mixin mx-0 {\n  @include mx-none;\n}\n\n@mixin margin-y($y: null) {\n  @include margin($y: $y);\n}\n\n///\n/// @alias margin-y()\n///\n@mixin my($y: null) {\n  @include margin-y($y: $y);\n}\n\n@mixin my-none {\n  @include my($y: 0);\n}\n\n///\n/// @alias my-none()\n///\n@mixin my-0 {\n  @include my-none;\n}\n\n@mixin margin-top($top: null) {\n  @include margin($top: $top);\n}\n\n///\n/// @alias margin-top()\n///\n@mixin mt($top: null) {\n  @include margin-top($top);\n}\n\n@mixin mt-none {\n  @include mt(0);\n}\n\n///\n/// @alias mt-none()\n///\n@mixin mt-0 {\n  @include mt-none;\n}\n\n@mixin margin-right($right: null) {\n  @include margin($right: $right);\n}\n\n///\n/// @alias margin-right()\n///\n@mixin mr($right: null) {\n  @include margin-right($right);\n}\n\n@mixin mr-none {\n  @include mr($right: 0);\n}\n\n///\n/// @alias mr-none()\n///\n@mixin mr-0 {\n  @include mr-none;\n}\n\n@mixin margin-bottom($bottom: null) {\n  @include margin($bottom: $bottom);\n}\n\n///\n/// @alias margin-bottom()\n///\n@mixin mb($bottom: null) {\n  @include margin-bottom($bottom: $bottom);\n}\n\n@mixin mb-none {\n  @include mb($bottom: 0);\n}\n\n///\n/// @alias mb-none()\n///\n@mixin mb-0 {\n  @include mb-none;\n}\n\n@mixin margin-left($left: null) {\n  @include margin($left: $left);\n}\n\n///\n/// @alias margin-left()\n///\n@mixin ml($left: null) {\n  @include margin-left($left: $left);\n}\n\n@mixin ml-none {\n  @include ml($left: 0);\n}\n\n///\n/// @alias ml-none()\n///\n@mixin ml-0 {\n  @include ml-none;\n}\n\n// padding\n\n@mixin padding(\n  $top: null,\n  $right: null,\n  $bottom: null,\n  $left: null,\n  $x: null,\n  $y: null,\n  $all: null,\n) {\n  @include -spacing(\n    $prop: padding,\n    $top: if($top, $top, if($y, $y, $all)),\n    $right: if($right, $right, if($x, $x, $all)),\n    $bottom: if($bottom, $bottom, if($y, $y, $all)),\n    $left: if($left, $left, if($x, $x, $all)),\n  );\n}\n\n///\n/// @alias padding()\n///\n@mixin p(\n  $a: null,\n  $x: null,\n  $y: null,\n  $t: null,\n  $r: null,\n  $b: null,\n  $l: null,\n) {\n  @include padding(\n    $all: $a,\n    $x: $x,\n    $y: $y,\n    $top: $t,\n    $right: $r,\n    $bottom: $b,\n    $left: $l,\n  );\n}\n\n@mixin padding-xy($x: null, $y: null) {\n  @include padding($x: $x, $y: $y);\n}\n\n///\n/// @alias padding-xy()\n///\n@mixin padding-axis($horizontal: null, $vertical: null) {\n  @include padding-xy($x: $horizontal, $y: $vertical);\n}\n\n@mixin padding-a