  $deg,\n//     colors.$red math.div(map.get($arrow, size), 2) + $offset,\n//     colors.$transparent math.div(map.get($arrow, size), 2) + $offset,\n//   );\n// }\n\n@each $placement, $prop in map.get($arrow, placements) {\n  .container[data-placement^='#{$placement}'] > .arrow {\n    #{$prop}: math.div(map.get($arrow, size), 2) * -1 + 1px;\n\n    // $mask-deg: map.get($arrow, mask-angles, $placement);\n\n    // @if $mask-deg {\n    //   &::before {\n    //     @include arrow-mask($mask-deg);\n    //   }\n    // }\n\n    &::before {\n      @if $placement == top {\n        top: -1px;\n      } @else if ($placement == right) {\n        right: -1px;\n      } @else if ($placement == bottom) {\n        bottom: -1px;\n      } @else if ($placement == left) {\n        left: -1px;\n      }\n    }\n  }\n}\n\n@mixin arrow-styles {\n  @include position.absolute;\n  width: map.get($arrow, size);\n  height: map.get($arrow, size);\n  background: inherit;\n}\n\n.arrow {\n  @include arrow-styles;\n  visibility: hidden;\n\n  &::before {\n    content: '';\n    @include arrow-styles;\n    transform: rotate(45deg);\n    visibility: visible;\n  }\n}\n","////\n/// @group spacing\n/// @access public\n/// @author Keith Choison <keith@tize.io>\n/// @since 0.1.0\n////\n\n@use 'functions/list';\n\n@mixin -spacing(\n  $prop,\n  $top: null,\n  $right: null,\n  $bottom: null,\n  $left: null,\n) {\n  @if not list.includes('margin' 'padding', $prop) {\n    @error 'Invalid $prop value passed to the -spacing() mixin: #{$prop}';\n  }\n\n  @if $top and $right and $bottom and $left { // all directions specified\n    @if $right == $left {\n      @if $top == $bottom {\n        @if $top == $right { // $top (== $bottom) == $right (== $left)\n          #{$prop}: $top;\n        } @else { // $top (== $bottom) != $right (== $left)\n          #{$prop}: $top $right;\n        }\n      } @else { // $top != $bottom, but $right == $left\n        #{$prop}: $top $right $bottom;\n      }\n    } @else { // $right != $left\n      #{$prop}: $top $right $bottom $left;\n    }\n  } @else { // not all directions specified\n    @if $top {\n      #{$prop}-top: $top;\n    }\n\n    @if $right {\n      #{$prop}-right: $right;\n    }\n\n    @if $bottom {\n      #{$prop}-bottom: $bottom;\n    }\n\n    @if $left {\n      #{$prop}-left: $left;\n    }\n  }\n}\n\n// margin\n\n@mixin margin(\n  $top: null,\n  $right: null,\n  $bottom: null,\n  $left: null,\n  $x: null,\n  $y: null,\n  $all: null,\n) {\n  @include -spacing(\n    $prop: margin,\n    $top: if($top, $top, if($y, $y, $all)),\n    $right: if($right, $right, if($x, $x, $all)),\n    $bottom: if($bottom, $bottom, if($y, $y, $all)),\n    $left: if($left, $left, if($x, $x, $all)),\n  );\n}\n\n///\n/// @alias margin()\n///\n@mixin m(\n  $a: null,\n  $x: null,\n  $y: null,\n  $t: null,\n  $r: null,\n  $b: null,\n  $l: null,\n) {\n  @include margin(\n    $all: $a,\n    $x: $x,\n    $y: $y,\n    $top: $t,\n    $right: $r,\n    $bottom: $b,\n    $left: $l,\n  );\n}\n\n@mixin margin-xy($x: null, $y: null) {\n  @include margin($x: $x, $y: $y);\n}\n\n///\n/// @alias margin-axis()\n///\n@mixin margin-axis($horizontal: null, $vertical: null) {\n  @include margin-xy($x: $horizontal, $y: $vertical);\n}\n\n@mixin margin-center {\n  @include margin($x: auto);\n}\n\n///\n/// @alias margin-center()\n///\n@mixin mx-auto {\n  @include margin-center;\n}\n\n@mixin margin-middle {\n  @include margin($y: auto);\n}\n\n///\n/// @alias margin-middle()\n///\n@mixin my-auto {\n  @include margin-middle;\n}\n\n@mixin margin-all($margin) {\n  @include margin($all: $margin);\n}\n\n///\n/// @alias margin-all()\n///\n@mixin margin-square($margin) {\n  @include margin-all($margin);\n}\n\n@mixin margin-auto {\n  @include margin-all(auto);\n}\n\n///\n/// @alias margin-auto()\n///\n@mixin m-auto {\n  @include margin-auto;\n}\n\n@mixin margin-none {\n  @include margin-all(0);\n}\n\n///\n/// @alias margin-none()\n///\n@mixin m-none {\n  @include margin-none;\n}\n\n///\n/// @alias m-none()\n///\n@mixin m-0 {\n  @include m-none;\n}\n\n@mixin margin-xy($x: null, $y: null) {\n  @include margin($x: $x, $y: $y);\n}\n\n///\n/// @alias margin-xy()\n///\n@mixin margin-axis($vertical: null, $horizontal: null) {\n  @include margin-xy($x: $horizontal, $y: $vertical);\n}\n\n@mixin margin-x($x: null) {\n  @include margin($x: $x);\n}\n\n///\n/// @alias margin-x()\n///\n@mixin mx($x: null) {\n  @include margin-x($x: $x);\n}\n\n@mixin mx-none {\n  @include mx($x: 0);\n}\n\n///\n/// @alias mx-none()\n///\n@mixin mx-0 {\n  @include mx-none;\n}\n\n@mixin margin-y($y: null) {\n  @include margin($y: $y);\n}\n\n///\n/// @alias margin-y()\n///\n@mixin my($y: null) {\n  @include margin-y($y: $y);\n}\n\n@mixin my-none {\n  @include my($y: 0);\n}\n\n///\n/// @alias my-none()\n///\n@mixin my-0 {\n  @include my-none;\n}\n\n@mixin margin-top($top: null) {\n  @include margin($top: $top);\n}\n\n///\n/// @alias margin-top()\n///\n@mixin mt($top: null) {\n  @include margin-top($top);\n}\n\n@mixin mt-none {\n  @include mt(0);\n}\n\n///\n/// @alias mt-none()\n///\n@mixin mt-0 {\n  @include mt-none;\n}\n\n@mixin margin-right($right: null) {\n  @include margin($right: $right);\n}\n\n///\n/// @alias margin-right()\n///\n@mixin mr($right: null) {\n  @include margin-right($right);\n}\n\n@mixin mr-none {\n  @include mr($right: 0);\n}\n\n///\n/// @alias mr-none()\n///\n@mixin mr-0 {\n  @include mr-none;\n}\n\n@mixin margin-bottom($bottom: null) {\n  @include margin($bottom: $bottom);\n}\n\n///\n/// @alias margin-bottom()\n///\n@mixin mb($bottom: null) {\n  @include margin-bottom($bottom: $bottom);\n}\n\n@mixin mb-none {\n  @include mb($bottom: 0);\n}\n\n///\n/// @alias mb-none()\n///\n@mixin mb-0 {\n  @include mb-none;\n}\n\n@mixin margin-left($left: null) {\n  @include margin($left: $left);\n}\n\n///\n/// @alias margin-left()\n///\n@mixin ml($left: null) {\n  @include margin-left($left: $left);\n}\n\n@mixin ml-none {\n  @include ml($left: 0);\n}\n\n///\n/// @alias ml-none()\n///\n@mixin ml-0 {\n  @include ml-none;\n}\n\n// padding\n\n@mixin padding(\n  $top: null,\n  $right: null,\n  $bottom: null,\n  $left: null,\n  $x: null,\n  $y: null,\n  $all: null,\n) {\n  @include -spacing(\n    $prop: padding,\n    $top: if($top, $top, if($y, $y, $all)),\n    $right: if($right, $right, if($x, $x, $all)),\n    $bottom: if($bottom, $bottom, if($y, $y, $all)),\n    $left: if($left, $left, if($x, $x, $all)),\n  );\n}\n\n///\n/// @alias padding()\n///\n@mixin p(\n  $a: null,\n  $x: null,\n  $y: null,\n  $t: null,\n  $r: null,\n  $b: null,\n  $l: null,\n) {\n  @include padding(\n    $all: $a,\n    $x: $x,\n    $y: $y,\n    $top: $t,\n    $right: $r,\n    $bottom: $b,\n    $left: $l,\n  );\n}\n\n@mixin padding-xy($x: null, $y: null) {\n  @include padding($x: $x, $y: $y);\n}\n\n///\n/// @alias padding-xy()\n///\n@mixin padding-axis($horizontal: null, $vertical: null) {\n  @include padding-xy($x: $horizontal, $y: $vertical);\n}\n\n@mixin padding-all($padding) {\n  @include padding($all: $padding);\n}\n\n///\n/// @alias padding-all()\n///\n@mixin padding-square($padding) {\n  @include padding-all($padding);\n}\n\n@mixin padding-none {\n  @include padding-all(0);\n}\n\n///\n/// @alias padding-none()\n///\n@mixin p-none {\n  @include padding-none;\n}\n\n///\n/// @alias p-none()\n///\n@mixin p-0 {\n  @include p-none;\n}\n\n@mixin padding-x($x: null) {\n  @include padding($x: $x);\n}\n\n///\n/// @alias padding-x()\n///\n@mixin px($x: null) {\n  @include padding-x($x);\n}\n\n@mixin px-none {\n  @include px(0);\n}\n\n///\n/// @alias px-none()\n///\n@mixin px-0 {\n  @include px-none;\n}\n\n@mixin padding-y($y: null) {\n  @include padding($y: $y);\n}\n\n///\n/// @alias padding-y()\n///\n@mixin py($y: null) {\n  @include padding-y($y);\n}\n\n@mixin py-none {\n  @include py(0);\n}\n\n///\n/// @alias py-none()\n///\n@mixin py-0 {\n  @include py-none;\n}\n\n@mixin padding-top($top: null) {\n  @include padding($top: $top);\n}\n\n///\n/// @alias padding-top()\n///\n@mixin pt($top: null) {\n  @include padding-top($top);\n}\n\n@mixin pt-none {\n  @include pt(0);\n}\n\n///\n/// @alias padding-top()\n///\n@mixin pt-0 {\n  @include pt-none;\n}\n\n@mixin padding-right($right: null) {\n  @include padding($right: $right);\n}\n\n///\n/// @alias padding-right()\n///\n@mixin pr($right: null) {\n  @include padding-right($right);\n}\n\n@mixin pr-none {\n  @include pr(0);\n}\n\n///\n/// @alias pr-none()\n///\n@mixin pr-0 {\n  @include pr-none;\n}\n\n@mixin padding-bottom($bottom: null) {\n  @include padding($bottom: $bottom);\n}\n\n///\n/// @alias padding-bottom()\n///\n@mixin pb($bottom: null) {\n  @include padding-bottom($bottom);\n}\n\n@mixin pb-none {\n  @include pb(0);\n}\n\n///\n/// @alias pb-none()\n///\n@mixin pb-0 {\n  @include pb-none;\n}\n\n@mixin padding-left($left: null) {\n  @include padding($left: $left);\n}\n\n///\n/// @alias padding-left()\n///\n@mixin pl($left: null) {\n  @include padding-left($left);\n}\n\n@mixin pl-none {\n  @include pl(0);\n}\n\n///\n/// @alias pl-none()\n///\n@mixin pl-0 {\n  @include pl-none;\n}\n","////\n/// @group font\n/// @access public\n/// @author Keith Choison <keith@tize.io>\n/// @since 0.1.0\n////\n\n@use 'sass:meta';\n@use 'sass:map';\n@use 'config/fonts';\n\n@mixin apply($font, $overrides: null) {\n  $props: (\n    'font-family',\n    'font-stretch',\n    'font-weight',\n  );\n\n  @each $prop in $props {\n    $value: map.get($font, $prop);\n\n    @if meta.type-of($overrides) == map and map.has-key($overrides, $prop) {\n      $value: map.get($overrides, $prop);\n    }\n\n    @if $value {\n      #{$prop}: $value;\n    } @else {\n      @warn 'Font prop `#{$prop}` was ignored because no value was set.';\n    }\n  }\n}\n\n///\n/// Applies the primary font.\n///\n@mixin primary($weight: 400) {\n  @include apply(fonts.$primary, ( font-weight: $weight ));\n}\n\n///\n/// Applies the monospaced font.\n///\n@mixin monospace($weight: 400) {\n  @include apply(fonts.$mono, ( font-weight: $weight ));\n}\n\n///\n/// @alias monospace()\n///\n@mixin mono($weight: 400) {\n  @include monospace($weight);\n}\n","////\n/// @group transition\n/// @author Keith Choison\n////\n\n@use 'sass:list';\n@use 'sass:meta';\n@use 'config/animations';\n\n@mixin apply($props...) {\n  $transitions: ();\n\n  @for $i from 1 through list.length($props) {\n    $prop: list.nth($props, $i);\n\n    $name: $prop;\n    $duration: animations.$transition-duration;\n    $function: animations.$transition-function;\n\n    @if meta.type-of($prop) == 'list' and list.length($prop) > 1 {\n      $name: list.nth($prop, 1);\n\n      @if list.nth($prop, 2) {\n        $duration: list.nth($prop, 2);\n      }\n\n      @if list.length($prop) > 2 and list.nth($prop, 3) {\n        $function: list.nth($prop, 3);\n      }\n    }\n\n    $transitions: list.append($transitions, '#{$name} #{$duration} #{$function}');\n  }\n\n  @if list.length($transitions) > 0 {\n    transition: #{list.zip($transitions)};\n  }\n}\n","$black: #000000;\n$white: #FFFFFF;\n\n$gray-lighter: #EEEEEE; // MD Gray 200\n$gray-light: #BDBDBD; // MD Gray 400\n$gray: #9E9E9E; // MD Gray 500\n$gray-dark: #424242; // MD Gray 800\n$gray-darker: #212121; // MD Gray 900\n$gray-darkest: #121212;\n\n$red: #F44336; // MD Red 500\n$green: #4CAF50; // MD Green 500\n$blue: #2196F3; // MD Blue 500\n\n$pink: #E91E63; // MD Pink 500\n$orange: #FF9800; // MD Orange 500\n$cyan: #00ACC1; // MD Cyan 500\n\n$transparent-black: rgba(0, 0, 0, 0);\n$transparent-white: rgba(255, 255, 255, 0);\n$transparent: $transparent-white;\n\n$showdown-background-light: #EEF2F5;\n$showdown-background-dark: #444444;\n","////\n/// @group position\n/// @access public\n/// @author Keith Choison <keith@tize.io>\n/// @since 0.1.0\n////\n\n@use 'sass:math';\n@use 'sass:meta';\n@use 'functions/list';\n\n///\n/// @access private\n///\n@mixin -inset(\n  $top: null,\n  $right: null,\n  $bottom: null,\n  $left: null,\n) {\n  @if $top {\n    top: $top;\n  }\n\n  @if $right {\n    right: $right;\n  }\n\n  @if $bottom {\n    bottom: $bottom;\n  }\n\n  @if $left {\n    left: $left;\n  }\n}\n\n@mixin inset(\n  $all: null,\n  $a: null,\n  $x: null,\n  $y: null,\n  $top: null,\n  $t: null,\n  $right: null,\n  $r: null,\n  $bottom: null,\n  $b: null,\n  $left: null,\n  $l: null,\n) {\n  @include -inset(\n    $top: if($top, $top, if($t, $t, if($y, $y, if($a, $a, $all)))),\n    $right: if($right, $right, if($r, $r, if($x, $x, if($a, $a, $all)))),\n    $bottom: if($bottom, $bottom, if($b, $b, if($y, $y, if($a, $a, $all)))),\n    $left: if($left, $left, if($l, $l, if($x, $x, if($a, $a, $all)))),\n  );\n}\n\n@mixin inset-all($all) {\n  @include inset($all: $all);\n}\n\n@mixin inset-none {\n  @include inset-all(0);\n}\n\n///\n/// @alias inset-none()\n///\n@mixin inset-0 {\n  @include inset-none;\n}\n\n@mixin inset-xy($x: null, $y: null) {\n  @include inset($x: $x, $y: $y);\n}\n\n@mixin inset-x($x) {\n  @include inset-xy($x: $x);\n}\n\n@mixin inset-x-none {\n  @include inset-x(0);\n}\n\n///\n/// @alias inset-x-none()\n///\n@mixin inset-x-0 {\n  @include inset-x-none;\n}\n\n@mixin inset-y($y) {\n  @include inset-xy($y: $y);\n}\n\n@mixin inset-y-none {\n  @include inset-y(0);\n}\n\n///\n/// @alias inset-y-none()\n///\n@mixin inset-y-0 {\n  @include inset-y-none;\n}\n\n@mixin top($top) {\n  @include inset($top: $top);\n}\n\n@mixin top-none {\n  @include top(0);\n}\n\n///\n/// @alias top-none()\n///\n@mixin top-0 {\n  @include top-none;\n}\n\n@mixin right($right) {\n  @include inset($right: $right);\n}\n\n@mixin right-none {\n  @include right(0);\n}\n\n///\n/// @alias right-none()\n///\n@mixin right-0 {\n  @include right-none;\n}\n\n@mixin bottom($bottom) {\n  @include inset($bottom: $bottom);\n}\n\n@mixin bottom-none {\n  @include bottom(0);\n}\n\n///\n/// @alias bottom-none()\n///\n@mixin bottom-0 {\n  @include bottom-none;\n}\n\n@mixin left($left) {\n  @include inset($left: $left);\n}\n\n@mixin left-none {\n  @include left(0);\n}\n\n///\n/// @alias left-none()\n///\n@mixin left-0 {\n  @