te, 0.3);\n$icon-light-color-hover: color.alpha(color.shade(colors.$blue, 15%), 0.95);\n$icon-dark-color-hover: color.alpha(colors.$blue, 0.95);\n\n$loading-indicator-light-color: color.alpha(colors.$black, 0.3);\n$loading-indicator-dark-color: color.alpha(colors.$white, 0.3);\n\n$indicator-separator-width: 1px;\n$indicator-separator-margin-x: 3px;\n$indicator-separator-light-color: colors.$transparent;\n$indicator-separator-dark-color: colors.$transparent;\n\n$menu-gutter: 2px; // distance between control and menu\n$menu-light-background-color: color.alpha(colors.$white, 0.975);\n$menu-dark-background-color: color.alpha(colors.$black, 0.975);\n// $menu-border-width: 1px;\n// $menu-light-border-color: color.alpha(colors.$black, 0.15);\n// $menu-dark-border-color: color.alpha(colors.$white, 0.15);\n$menu-z-index: 10;\n\n/// @todo disgusting lol\n$option-padding-x: 3px;\n$option-padding-y: 2px;\n$option-light-color: colors.$black;\n$option-dark-color: colors.$white;\n$option-light-color-selected: colors.$white; // might as well add to the steaming pile of poo\n$option-dark-color-selected: colors.$white; // lolol\n$option-light-background-color: colors.$transparent;\n$option-dark-background-color: colors.$transparent;\n$option-light-background-color-hover: color.alpha(colors.$black, 0.15);\n$option-dark-background-color-hover: color.alpha(colors.$white, 0.15);\n$option-light-background-color-focused: color.alpha(colors.$blue, 0.2);\n$option-dark-background-color-focused: color.alpha(colors.$blue, 0.25);\n$option-light-background-color-focused-hover: color.alpha(colors.$blue, 0.5);\n$option-dark-background-color-focused-hover: color.alpha(colors.$blue, 0.5);\n$option-light-background-color-selected: color.alpha(color.shade(colors.$blue, 15%), 0.9);\n$option-dark-background-color-selected: color.alpha(colors.$blue, 0.9);\n$option-light-background-color-selected-hover: color.alpha(color.shade(colors.$blue, 10%), 0.75);\n$option-dark-background-color-selected-hover: color.alpha(color.shade(colors.$blue, 5%), 0.75);\n\n$option-right-label-spacing: 3px; // basically margin-left\n$option-right-label-font-size: 8px;\n$option-right-label-light-color: color.alpha($option-light-color, 0.75);\n$option-right-label-dark-color: color.alpha($option-dark-color, 0.75);\n\n$option-sub-label-font-size: 8px;\n$option-sub-label-light-color: color.alpha($option-light-color, 0.75);\n$option-sub-label-dark-color: color.alpha($option-dark-color, 0.75);\n\n$notice-padding-x: $option-padding-x;\n$notice-padding-y: $option-padding-y;\n$notice-light-color: color.alpha(colors.$black, 0.5);\n$notice-dark-color: color.alpha(colors.$white, 0.5);\n\n$group-padding-x: 1px;\n\n$group-heading-padding-x: $option-padding-x + 2px;\n$group-heading-padding-y: $option-padding-y + 2px;\n$group-heading-font-weight: 500;\n$group-heading-font-size: 8px;\n$group-heading-letter-spacing: 0.5px;\n$group-heading-light-color: color.alpha(colors.$black, 0.85);\n$group-heading-dark-color: color.alpha(colors.$white, 0.85);\n$group-heading-light-background-color: colors.$gray-lighter;\n$group-heading-dark-background-color: colors.$gray-darker;\n\n.container {\n  position: relative;\n}\n\n// SelectContainer\n\n.selectContainer {\n  position: relative;\n  @include flex.row;\n  // border: $border-width solid colors.$transparent;\n  border-radius: $border-radius;\n  @include transition.apply(background-color, box-shadow);\n\n  .light & {\n    background-color: map.get($background-color, default, light);\n    // border-color: $border-color-light;\n    box-shadow: map.get($box-shadow, default, light);\n  }\n\n  .dark & {\n    background-color: map.get($background-color, default, dark);\n    // border-color: $border-color-dark;\n    box-shadow: map.get($box-shadow, default, dark);\n  }\n\n  &:not(.active):hover {\n    .light & {\n      background-color: map.get($background-color, hover, light);\n      box-shadow: map.get($box-shadow, hover, light);\n    }\n\n    .dark & {\n      background-color: map.get($background-color, hover, dark);\n      box-shadow: map.get($box-shadow, hover, dark);\n    }\n  }\n\n  &.active {\n    .light & {\n      background-color: map.get($background-color, active, light);\n    }\n\n    .dark & {\n      background-color: map.get($background-color, active, dark);\n    }\n  }\n\n  &.highlight {\n    .light & {\n      background-color: map.get($background-color, highlight, light);\n      box-shadow: map.get($box-shadow, highlight, light);\n    }\n\n    .dark & {\n      background-color: map.get($background-color, highlight, dark);\n      box-shadow: map.get($box-shadow, highlight, dark);\n    }\n  }\n\n  &.rtl {\n    direction: rtl;\n  }\n\n  &.disabled {\n    opacity: $opacity-disabled;\n    pointer-events: none;\n  }\n}\n\n// SelectControl\n\n.control {\n  position: relative;\n  @include flex.row-between;\n  // flex-wrap: wrap;\n  width: 100%;\n  @include spacing.padding-xy($padding-x, $padding-y);\n  outline: none;\n\n  i:global(.fa) {\n    font-size: $icon-size;\n    line-height: $icon-size + 1px;\n  }\n}\n\n// SelectValueContainer\n\n.valueContainer {\n  position: relative;\n  @include flex.row($align: center);\n  flex: 1;\n  flex-wrap: wrap;\n  @include transition.apply(color);\n  cursor: text;\n\n  .light & {\n    color: map.get($value, color, default, light);\n  }\n\n  .dark & {\n    color: map.get($value, color, default, dark);\n  }\n\n  .selectContainer:not(.active):hover & {\n    .light & {\n      color: map.get($value, color, hover, light);\n    }\n\n    .dark & {\n      color: map.get($value, color, hover, dark);\n    }\n  }\n\n  .selectContainer.active &.menuOpen {\n    .light & {\n      color: map.get($value, color, active, light);\n    }\n\n    .dark & {\n      color: map.get($value, color, active, dark);\n    }\n  }\n\n  .selectContainer.highlight & {\n    .light & {\n      color: map.get($value, color, highlight, light);\n    }\n\n    .dark & {\n      color: map.get($value, color, highlight, dark);\n    }\n  }\n}\n\n.value {\n  position: relative;\n  width: 100%;\n\n  // &.single {\n  //   width: 100%;\n  // }\n\n  &.multi {\n    @include flex.row;\n    flex-wrap: wrap;\n  }\n}\n\n// SelectPlaceholder\n\n.placeholder {\n  @include position.absolute-anchor($y: 50%);\n  font-size: map.get($value, font-size);\n  text-overflow: ellipsis;\n  white-space: nowrap;\n  overflow: hidden;\n  @include transition.apply(color);\n  user-select: none;\n  pointer-events: none;\n\n  .light & {\n    color: $placeholder-light-color;\n  }\n\n  .dark & {\n    color: $placeholder-dark-color;\n  }\n\n  .selectContainer:not(.active):hover & {\n    .light & {\n      color: $placeholder-light-color-hover;\n    }\n\n    .dark & {\n      color: $placeholder-dark-color-hover;\n    }\n  }\n\n  .selectContainer.active & {\n    .light & {\n      color: $placeholder-light-color-active;\n    }\n\n    .dark & {\n      color: $placeholder-dark-color-active;\n    }\n  }\n}\n\n// SelectInput\n\n.inputContainer {\n  display: inline-grid;\n  grid-template-columns: 0 1fr;\n\n  &::after {\n    content: attr(data-value) ' ';\n    grid-area: 1 / 2;\n    min-width: 2px;\n    @include spacing.margin-none;\n    @include spacing.padding-none;\n    border: none;\n    outline: none;\n    white-space: nowrap;\n    visibility: hidden;\n  }\n\n  &.disabled {\n    visibility: hidden;\n  }\n}\n\n.input {\n  grid-area: 1 / 2;\n  min-width: 2px;\n  @include spacing.margin-none;\n  @include spacing.padding-none;\n  @include font.apply(fonts.$mono);\n  font-size: map.get($value, font-size);\n  background: none;\n  border: none;\n  outline: none;\n  opacity: 1;\n\n  .light & {\n    color: map.get($value, color, default, light);\n  }\n\n  .dark & {\n    color: map.get($value, color, default, dark);\n  }\n\n  &.hidden {\n    opacity: 0;\n  }\n}\n\n// SelectGroup\n\n.group {\n  position: sticky;\n  top: 0;\n}\n\n// SelectGroupHeading\n\n.groupHeading {\n  display: block;\n  // @include spacing.margin($x: -1px);\n  @include spacing.padding($x: $group-heading-padding-x, $y: $group-heading-padding-y);\n  @include font.apply(fonts.$primary, ( font-weight: $group-heading-font-weight ));\n  font-size: $group-heading-font-size;\n  letter-spacing: $group-heading-letter-spacing;\n  text-indent: $group-heading-letter-spacing;\n  text-transform: uppercase;\n  user-select: none;\n  cursor: default;\n\n  .light & {\n    color: $group-heading-light-color;\n    background-color: $group-heading-light-background-color;\n  }\n\n  .dark & {\n    color: $group-heading-dark-color;\n    background-color: $group-heading-dark-background-color;\n  }\n}\n\n// SelectSingleValue\n\n.singleValue {\n  @include position.absolute-anchor($y: 50%);\n  max-width: 100%;\n  font-size: map.get($value, font-size);\n  white-space: nowrap;\n  text-overflow: ellipsis;\n  overflow: hidden;\n  // pointer-events: none; // strangely causes the dropdown to close on mouse up in the Calcdex overlay\n\n  .highlight & {\n    font-weight: 500;\n  }\n}\n\n// SelectMultiValue\n\n.mutliValue {\n  @include flex.row-center;\n  @include spacing.margin-xy($multi-value-padding-x, $multi-value-padding-y);\n  font-size: map.get($value, font-size) - ($multi-value-padding-y * 2);\n  border: 1px solid colors.$transparent;\n\n  .light & {\n    border-color: $multi-value-light-border-color;\n  }\n\n  .dark & {\n    border-color: $multi-value-dark-border-color;\n  }\n}\n\n.valueLabel {\n  @include spacing.padding-xy($multi-value-padding-x, $multi-value-padding-y);\n  font-size: map.get($value, font-size) - ($multi-value-padding-y * 2);\n  white-space: nowrap;\n  overflow: hidden;\n\n  &.crop {\n    text-overflow: ellipsis;\n  }\n}\n\n.remove {\n  @include flex.row-center;\n  @include spacing.padding($right: $multi-value-padding-x);\n  @include transition.apply(color);\n  cursor: pointer;\n\n  .light & {\n    color: $icon-light-color;\n  }\n\n  .dark & {\n    color: $icon-dark-color;\n  }\n\n  &:hover {\n    .light & {\n      color: $icon-light-color-hover;\n    }\n\n    .dark & {\n      color: $icon-dark-color-hover;\n    }\n  }\n}\n\n// SelectIndicatorsContainer\n\n.indicatorsContainer {\n  @include flex.row($align: center);\n  flex-shrink: 0;\n  align-self: stretch;\n}\n\n.indicator {\n  display: flex;\n  @include transition.apply(color);\n  cursor: pointer;\n\n  .light & {\n    color: $icon-light-color;\n  }\n\n  .dark & {\n    color: $icon-dark-color;\n  }\n\n  &:hover {\n    .light & {\n      color: $icon-light-color-hover;\n    }\n\n    .dark & {\n      color: $icon-dark-color-hover;\n    }\n  }\n}\n\n// SelectDropdownIndicator\n\n.dropdownIndicator {\n  .selectContainer:not(.active):hover &:not(:hover) {\n    .light & {\n      color: color.alpha($icon-light-color-hover, 0.48);\n    }\n\n    .dark & {\n      color: color.alpha($icon-dark-color-hover, 0.48);\n    }\n  }\n\n  i {\n    @include transition.apply(transform);\n\n    .menuOpen & {\n      transform: rotate(-180deg);\n    }\n  }\n}\n\n// SelectLoadingIndicator\n\n.loadingIndicator {\n  @include flex.row;\n  align-self: center;\n  vertical-align: middle;\n  line-height: 1;\n  text-align: center;\n  @include transition.apply(color);\n\n  .light & {\n    color: $loading-indicator-light-color;\n  }\n\n  .dark & {\n    color: $loading-indicator-dark-color;\n  }\n}\n\n@keyframes loadingIndicatorDotAnimation {\n  0%, 80%, 100% {\n    opacity: 0;\n  }\n\n  40% {\n    opacity: 1;\n  }\n}\n\n.loadingIndicatorDot {\n  display: inline-block;\n  vertical-align: top;\n  width: 1em;\n  height: 1em;\n  background-color: currentColor;\n  border-radius: 1em;\n  animation: loadingIndicatorDotAnimation 1s ease-in-out infinite;\n\n  &.offset {\n    @include spacing.margin($left: 1em);\n  }\n}\n\n// SelectIndicatorSeparator\n\n.indicatorSeparator {\n  align-self: stretch;\n  width: $indicator-separator-width;\n  @include spacing.margin($x: $indicator-separator-margin-x);\n\n  .light & {\n    background: $indicator-separator-light-color;\n  }\n\n  .dark & {\n    background: $indicator-separator-dark-color;\n  }\n}\n\n// SelectMenu\n\n.menu {\n  position: absolute;\n  width: 100%;\n  @include spacing.margin($x: 0, $y: $menu-gutter);\n  border-radius: $border-radius;\n  // border: $menu-border-width solid colors.$transparent;\n  overflow: hidden;\n  z-index: $menu-z-index;\n\n  .light & {\n    background-color: $menu-light-background-color;\n    // border-color: $menu-light-border-color;\n    box-shadow: map.get($box-shadow, default, light);\n  }\n\n  .dark & {\n    background-color: $menu-dark-background-color;\n    // border-color: $menu-dark-border-color;\n    box-shadow: map.get($box-shadow, default, dark);\n  }\n\n  &.placementTop {\n    bottom: 100%;\n  }\n\n  &.placementBottom {\n    top: 100%;\n  }\n}\n\n// SelectMenuList\n\n.menuList {\n  position: relative;\n  // overflow-y: auto;\n  overflow: hidden scroll;\n}\n\n// SelectOption\n\n.option {\n  @include flex.column;\n  width: 100%;\n  @include spacing.padding($x: $option-padding-x, $y: $option-padding-y);\n  font-size: map.get($value, font-size);\n  @include transition.apply(background-color);\n  user-select: none;\n  cursor: pointer;\n\n  .light & {\n    background-color: $option-light-background-color;\n  }\n\n  .dark & {\n    background-color: $option-dark-background-color;\n  }\n\n  &:hover {\n    .light & {\n      background-color: $option-light-background-color-hover;\n    }\n\n    .dark & {\n      background-color: $option-dark-background-color-hover;\n    }\n  }\n\n  &.focused {\n    .light & {\n      background-color: $option-light-background-color-focused;\n\n      &:hover {\n        background-color: $option-light-background-color-focused-hover;\n      }\n    }\n\n    .dark & {\n      background-color: $option-dark-background-color-focused;\n\n      &:hover {\n        background-color: $option-dark-background-color-focused-hover;\n      }\n    }\n  }\n\n  &.selected {\n    .light & {\n      background-color: $option-light-background-color-selected;\n\n      &:hover {\n        background-color: $option-light-background-color-selected-hover;\n      }\n    }\n\n    .dark & {\n      background-color: $option-dark-background-color-selected;\n\n      &:hover {\n        background-color: $option-dark-background-color-selected-hover;\n      }\n    } // end .dark &\n  } // end &.selected\n\n  &.disabled {\n    opacity: $opacity-disabled;\n    pointer-events: none;\n  }\n}\n\n.optionRow {\n  @include flex.row-between;\n  width: 100%;\n\n  .light & {\n    color: $option-light-color;\n  }\n\n  .dark & {\n    color: $option-dark-color;\n  }\n\n  .selected & {\n    .light & {\n      color: $option-light-color-selected;\n    }\n\n    .dark & {\n      color: $option-dark-color-selected;\n    }\n  }\n}\n\n// .optionLabel {\n//   flex: 2 0;\n// }\n\n.optionRightLabel {\n  // flex: 1;\n  @include spacing.margin($left: $option-right-label-spacing);\n  font-size: $option-right-label-font-size;\n  text-align: right;\n\n  .light & {\n    color: $option-right-label-light-color;\n  }\n\n  .dark & {\n    color: $option-right-label-dark-color;\n  }\n\n  .selected & {\n    .light & {\n      color: inherit;\n    }\n\n    .dark & {\n      color: inherit;\n    }\n  }\n}\n\n.optionSubLabel {\n  font-size: $option-sub-label-font-size;\n\n  .light & {\n    color: $option-sub-label-light-color;\n  }\n\n  .dark & {\n    color: $option-sub-label-dark-color;\n  }\n\n  // note: .optionSubLabel is not inside .optionRow, so it's not possible\n  // to inherit .optionRow's color here (like in .optionRightLabel)\n  .selected & {\n    .light & {\n      color: $option-light-color-selected;\n    }\n\n    .dark & {\n      color: $option-dark-color-selected;\n    }\n  }\n}\n\n.optionItem {\n  &:first-child {\n    border-radius: $border-radius $border-radius 0 0;\n  }\n\n  &:last-child {\n    border-radius: 0 0 $border-radius $border-radius;\n  }\n}\n\n// SelectNotice\n\n.notice {\n  @include spacing.padding($x: $notice-padding-x, $y: $notice-padding-y);\n  font-size: map.get($value, font-size);\n  text-align: center;\n  user-select: none;\n\n  .light & {\n    color: $notice-light-color;\n  }\n\n  .dark & {\n    color: $notice-dark-color;\n  }\n}\n","///\n/// @group flex\n/// @access public\n/// @author Keith Choison <keith@tize.io>\n/// @since 0.1.0\n///\n\n///\n/// @access private\n///\n@mixin -flex(\n  $direction: null,\n  $justify: null,\n  $align: null,\n  $inline: false,\n) {\n  display: if($inline, inline-flex, flex);\n\n  @if $direction and $direction != row {\n    flex-direction: $direction;\n  }\n\n  @if $justify and $justify != flex-start {\n    justify-content: $justify;\n  }\n\n  @if $align and $align != stretch {\n    align-items: $align;\n  }\n}\n\n// rows\n\n@mixin row(\n  $justify: null,\n  $align: null,\n  $reverse: false,\n  $inline: false,\n) {\n  @include -flex(\n    if($reverse, row-reverse, row),\n    $justify,\n    $align,\n    $inline,\n  );\n}\n\n@mixin row-stretch($reverse: false, $inline: false) {\n  @include row(stretch, stretch, $reverse, $inline);\n}\n\n///\n/// @alias row-stretch()\n///\n@mixin stretch($reverse: false, $inline: false) {\n  @include row-stretch($reverse, $inline);\n}\n\n@mixin row-start($align: center, $reverse: false, $inline: false) {\n  @include row(flex-start, $align, $reverse, $inline);\n}\n\n///\n/// @alias row-start()\n///\n@mixin start($align: center, $reverse: false, $inline: false) {\n  @include row-start($align, $reverse, $inline);\n}\n\n@mixin row-start-stretch($reverse: false, $inline: false) {\n  @include row-start(stretch, $reverse, $inline);\n}\n\n///\n/// @alias row-start-stretch()\n///\n@mixin start-stretch($reverse: false, $inline: false) {\n  @include row-start-stretch($reverse, $inline);\n}\n\n@mixin row-center($align: center, $reverse: false, $inline: false) {\n  @include row(center, $align, $reverse, $inline);\n}\n\n///\n/// @alias row-center()\n///\n@mixin center($align: center, $reverse: false, $inline: false) {\n  @include row-center($align, $reverse, $inline);\n}\n\n@mixin row-center-stretch($reverse: false, $inline: false) {\n  @include row-center(stretch, $reverse, $inline);\n}\n\n///\n/// @alias row-center-stretch()\n///\n@mixin center-stretch($reverse: false, $inline: false) {\n  @include row-center-stretch($reverse, $inline);\n}\n\n@mixin row-end($align: center, $reverse: false, $inline: false) {\n  @include row(flex-end, $align, $reverse, $inline);\n}\n\n///\n/// @alias row-end()\n///\n@mixin end($align: center, $reverse: false, $inline: false) {\n  @include row-end($align, $reverse, $inline);\n}\n\n@mixin row-end-stretch($reverse: false, $inline: false) {\n  @include row-end(stretch, $reverse, $inline);\n}\n\n///\n/// @alias row-end-stretch()\n///\n@mixin end-stretch($reverse: false, $inline: false) {\n  @include row-end-stretch($reverse, $inline);\n}\n\n@mixin row-between($align: center, $reverse: false, $inline: false) {\n  @include row(space-between, $align, $reverse, $inline);\n}\n\n///\n/// @alias row-between()\n///\n@mixin between($align: center, $reverse: false, $inline: false) {\n  @include row-between($align, $reverse, $inline);\n}\n\n@mixin row-between-stretch($reverse: false, $inline: false) {\n  @include row-between(stretch, $reverse, $inline);\n}\n\n///\n/// @alias row-between-stretch()\n///\n@mixin between-stretch($reverse: false, $inline: false) {\n  @include row-between-stretch($reverse, $inline);\n}\n\n@mixin row-around($align: center, $reverse: false, $inline: false) {\n  @include row(space-around, $align, $reverse, $inline);\n}\n\n///\n/// @alias row-around()\n///\n@mixin around($align: center, $reverse: false, $inline: false) {\n  @include row-around($align, $reverse, $inline);\n}\n\n@mixin row-around-stretch($reverse: false, $inline: false) {\n  @include row-around(stretch, $reverse, $inline);\n}\n\n///\n/// @alias row-around-stretch()\n///\n@mixin around-stretch($reverse: false, $inline: false) {\n  @include row-around-stretch($reverse, $inline);\n}\n\n@mixin row-evenly($align: center, $reverse: false, $inline: false) {\n  @include row(space-evenly, $align, $reverse, $inline);\n}\n\n///\n/// @alias row-evenly()\n///\n@mixin evenly($align: center, $reverse: false, $inline: false) {\n  @include row-evenly($align, $reverse, $inline);\n}\n\n@mixin row-evenly-stretch($reverse: false, $inline: false) {\n  @include row-evenly(stretch, $reverse, $inline);\n}\n\n///\n/// @alias row-evenly-stretch()\n///\n@mixin evenly-stretch($reverse: false, $inline: false) {\n  @include row-evenly-stretch($reverse, $inline);\n}\n\n// columns\n\n@mixin column(\n  $justify: null,\n  $align: null,\n  $reverse: false,\n  $inline: false,\n) {\n  @include -flex(\n    if($reverse, column-reverse, column),\n    $justify,\n    $align,\n    $inline,\n  );\n}\n\n///\n/// @alias column()\n///\n@mixin col(\n  $justify: null,\n  $align: null,\n  $reverse: false,\n  $inline: false,\n) {\n  @include column($justify, $align, $reverse, $inline);\n}\n\n@mixin column-stretch($reverse: false, $inline: false) {\n  @include column(stretch, stretch, $reverse, $inline);\n}\n\n///\n/// @alias column-stretch()\n///\n@mixin col-stretch($reverse: false, $inline: false) {\n  @include column-stretch($reverse, $inline);\n}\n\n@mixin column-start($align: center, $reverse: false, $inline: false) {\n  @include column(flex-start, $align, $reverse, $inline);\n}\n\n///\n/// @alias column-start()\n///\n@mixin col-start($align: center, $reverse: false, $inline: false) {\n  @include column-start($align, $reverse, $inline);\n}\n\n@mixin column-start-stretch($reverse: false, $inline: false) {\n  @include column-start(stretch, $reverse, $inline);\n}\n\n///\n/// @alias column-start-stretch()\n///\n@mixin col-start-stretch($reverse: false, $inline: false) {\n  @include column-start-stretch($reverse, $inline);\n}\n\n@mixin column-center($align: center, $reverse: false, $inline: false) {\n  @include column(center, $align, $reverse, $inline);\n}\n\n///\n/// @alias column-center()\n///\n@mixin col-center($align: center, $reverse: false, $inline: false) {\n  @include column-center($align, $reverse, $inline);\n}\n\n@mixin column-center-stretch($reverse: false, $inline: false) {\n  @include column-center(stretch, $reverse, $inline);\n}\n\n///\n/// @alias column-center-stretch()\n///\n@mixin col-center-stretch($reverse: false, $inline: false) {\n  @include column-center-stretch($reverse, $inline);\n}\n\n@mixin column-end($align: center, $reverse: false, $inline: false) {\n  @include column(flex-end, $align, $reverse, $inline);\n}\n\n///\n/// @alias column-end()\n///\n@mixin col-end($align: center, $reverse: false, $inline: false) {\n  @include column-end($align, $reverse, $inline);\n}\n\n@mixin column-end-stretch($reverse: false, $inline: false) {\n  @include column-end(stretch, $reverse, $inline);\n}\n\n///\n/// @alias column-end-stretch()\n///\n@mixin col-end-stretch($reverse: false, $inline: false) {\n  @include column-end-stretch($reverse, $inline);\n}\n\n@mixin column-between($align: center, $reverse: false, $inline: false) {\n  @include column(space-between, $align, $reverse, $inline);\n}\n\n///\n/// @alias column-between()\n///\n@mixin col-between($align: center, $reverse: false, $inline: false) {\n  @include column-between($align, $reverse, $inline);\n}\n\n@mixin column-between-stretch($reverse: false, $inline: false) {\n  @include column-between(stretch, $reverse, $inline);\n}\n\n///\n/// @alias column-between-stretch()\n///\n@mixin col-between-stretch($reverse: false, $inline: false) {\n  @include column-between-stretch($reverse, $inline);\n}\n\n@mixin column-around($align: center, $reverse: false, $inline: false) {\n  @include column(space-around, $align, $reverse, $inline);\n}\n\n///\n/// @alias column-around()\n///\n@mixin col-around($align: center, $reverse: false, $inline: false) {\n  @include column-around($align, $reverse, $inline);\n}\n\n@mixin column-around-stretch($reverse: false, $inline: false) {\n  @include column-around(stretch, $reverse, $inline);\n}\n\n///\n/// @alias column-around-stretch()\n///\n@mixin col-around-stretch($reverse: false, $inline: false) {\n  @include column-around-stretch($reverse, $inline);\n}\n\n@mixin column-evenly($align: center, $reverse: false, $inline: false) {\n  @include column(space-evenly, $align, $reverse, $inline);\n}\n\n///\n/// @alias column-evenly()\n///\n@mixin col-evenly($align: center, $reverse: false, $inline: false) {\n  @include column-evenly($align, $reverse, $inline);\n}\n\n@mixin column-evenly-stretch($reverse: false, $inline: false) {\n  @include column-evenly(stretch, $reverse, $inline);\n}\n","////\n/// @group transition\n/// @author Keith Choison\n////\n\n@use 'sass:list';\n@use 'sass:meta';\n@use 'config/animations';\n\n@mixin apply($props...) {\n  $transitions: ();\n\n  @for $i from 1 through list.length($props) {\n    $prop: list.nth($props, $i);\n\n    $name: $prop;\n    $duration: animations.$transition-duration;\n    $function: animations.$transition-function;\n\n    @if meta.type-of($prop) == 'list' and list.length($prop) > 1 {\n      $name: list.nth($prop, 1);\n\n      @if list.nth($prop, 2) {\n        $duration: list.nth($prop, 2);\n      }\n\n      @if list.length($prop) > 2 and list.nth($prop, 3) {\n        $function: list.nth($prop, 3);\n      }\n    }\n\n    $transitions: list.append($transitions, '#{$name} #{$duration} #{$function}');\n  }\n\n  @if list.length($transitions) > 0 {\n    transition: #{list.zip($transitions)};\n  }\n}\n","////\n/// @group spacing\n/// @access public\n/// @author Keith Choison <keith@tize.io>\n/// @since 0.1.0\n////\n\n@use 'functions/list';\n\n@mixin -spacing(\n  $prop,\n  $top: null,\n  $right: null,\n  $bottom: null,\n  $left: null,\n) {\n  @if not list.includes('margin' 'padding', $prop) {\n    @error 'Invalid $prop value passed to the -spacing() mixin: #{$prop}';\n  }\n\n  @if $top and $right and $bottom and $left { // all directions specified\n    @if $right == $left {\n      @if $top == $bottom {\n        @if $top == $right { // $top (== $bottom) == $right (== $left)\n          #{$prop}: $top;\n        } @else { // $top (== $bottom) != $right (== $left)\n          #{$prop}: $top $right;\n        }\n      } @else { // $top != $bottom, but $right == $left\n        #{$prop}: $top $right $bottom;\n      }\n    } @else { // $right != $left\n      #{$prop}: $top $right $bottom $left;\n    }\n  } @else { // not all directions specified\n    @if $top {\n      #{$prop}-top: $top;\n    }\n\n    @if $right {\n      #{$prop}-right: $right;\n    }\n\n    @if $bottom {\n      #{$prop}-bottom: $bottom;\n    }\n\n    @if $left {\n      #{$prop}-left: $left;\n    }\n  }\n}\n\n// margin\n\n@mixin margin(\n  $top: null,\n  $right: null,\n  $bottom: null,\n  $left: null,\n  $x: null,\n  $y: null,\n  $all: null,\n) {\n  @include -spacing(\n    $prop: margin,\n    $top: if($top, $top, if($y, $y, $all)),\n    $right: if($right, $right, if($x, $x, $all)),\n    $bottom: if($bottom, $bottom, if($y, $y, $all)),\n    $left: if($left, $left, if($x, $x, $all)),\n  );\n}\n\n///\n/// @alias margin()\n///\n@mixin m(\n  $a: null,\n  $x: null,\n  $y: null,\n  $t: null,\n  $r: null,\n  $b: null,\n  $l: null,\n) {\n  @include margin(\n    $all: $a,\n    $x: $x,\n    $y: $y,\n    $top: $t,\n    $right: $r,\n    $bottom: $b,\n    $left: $l,\n  );\n}\n\n@mixin margin-xy($x: null, $y: null) {\n  @include margin($x: $x, $y: $y);\n}\n\n///\n/// @alias margin-axis()\n///\n@mixin margin-axis($horizontal: null, $vertical: null) {\n  @include margin-xy($x: $horizontal, $y: $vertical);\n}\n\n@mixin margin-center {\n  @include margin($x: auto);\n}\n\n///\n/// @alias margin-center()\n///\n@mixin mx-auto {\n  @include margin-center;\n}\n\n@mixin margin-middle {\n  @include margin($y: auto);\n}\n\n///\n/// @alias margin-middle()\n///\n@mixin my-auto {\n  @include margin-middle;\n}\n\n@mixin margin-all($margin) {\n  @include margin($all: $margin);\n}\n\n///\n/// @alias margin-all()\n///\n@mixin margin-square($margin) {\n  @include margin-all($margin);\n}\n\n@mixin margin-auto {\n  @include margin-all(auto);\n}\n\n///\n/// @alias margin-auto()\n///\n@mixin m-auto {\n  @include margin-auto;\n}\n\n@mixin margin-none {\n  @include margin-all(0);\n}\n\n///\n/// @alias margin-none()\n///\n@mixin m-none {\n  @include margin-none;\n}\n\n///\n/// @alias m-none()\n///\n@mixin m-0 {\n  @include m-none;\n}\n\n@mixin margin-xy($x: null, $y: null) {\n  @include margin($x: $x, $y: $y);\n}\n\n///\n/// @alias margin-xy()\n///\n@mixin margin-axis($vertical: null, $horizontal: null) {\n  @include margin-xy($x: $horizontal, $y: $vertical);\n}\n\n@mixin margin-x($x: null) {\n  @include margin($x: $x);\n}\n\n///\n/// @alias margin-x()\n///\n@mixin mx($x: null) {\n  @include margin-x($x: $x);\n}\n\n@mixin mx-none {\n  @include mx($x: 0);\n}\n\n///\n/// @alias mx-none()\n///\n@mixin mx-0 {\n  @include mx-none;\n}\n\n@mixin margin-y($y: null) {\n  @include margin($y: $y);\n}\n\n///\n/// @alias margin-y()\n///\n@mixin my($y: null) {\n  @include margin-y($y: $y);\n}\n\n@mixin my-none {\n  @include my($y: 0);\n}\n\n///\n/// @alias my-none()\n///\n@mixin my-0 {\n  @include my-none;\n}\n\n@mixin margin-top($top: null) {\n  @include margin($top: $top);\n}\n\n///\n/// @alias margin-top()\n///\n@mixin mt($top: null) {\n  @include margin-top($top);\n}\n\n@mixin mt-none {\n  @include mt(0);\n}\n\n///\n/// @alias mt-none()\n///\n@mixin mt-0 {\n  @include mt-none;\n}\n\n@mixin margin-right($right: null) {\n  @include margin($right: $right);\n}\n\n///\n/// @alias margin-right()\n///\n@mixin mr($right: null) {\n  @include margin-right($right);\n}\n\n@mixin mr-none {\n  @include mr($right: 0);\n}\n\n///\n/// @alias mr-none()\n///\n@mixin mr-0 {\n  @include mr-none;\n}\n\n@mixin margin-bottom($bottom: null) {\n  @include margin($bottom: $bottom);\n}\n\n///\n/// @alias margin-bottom()\n///\n@mixin mb($bottom: null) {\n  @include margin-bottom($bottom: $bottom);\n}\n\n@mixin mb-none {\n  @include mb($bottom: 0);\n}\n\n///\n/// @alias mb-none()\n///\n@mixin mb-0 {\n  @include mb-none;\n}\n\n@mixin margin-left($left: null) {\n  @include margin($left: $left);\n}\n\n///\n/// @alias margin-left()\n///\n@mixin ml($left: null) {\n  @include margin-left($left: $left);\n}\n\n@mixin ml-none {\n  @include ml($left: 0);\n}\n\n///\n/// @alias ml-none()\n///\n@mixin ml-0 {\n  @include ml-none;\n}\n\n// padding\n\n@mixin padding(\n  $top: null,\n  $right: null,\n  $bottom: null,\n  $left: null,\n  $x: null,\n  $y: null,\n  $all: null,\n) {\n  @include -spacing(\n    $prop: padding,\n    $top: if($top, $top, if($y, $y, $all)),\n    $right: if($right, $right, if($x, $x, $all)),\n    $bottom: if($bottom, $bottom, if($y, $y, $all)),\n    $left: if($left, $left, if($x, $x, $all)),\n  );\n}\n\n///\n/// @alias padding()\n///\n@mixin p(\n  $a: null,\n  $x: null,\n  $y: null,\n  $t: null,\n  $r: null,\n  $b: null,\n  $l: null,\n) {\n  @include padding(\n    $all: $a,\n    $x: $x,\n    $y: $y,\n    $top: $t,\n    $right: $r,\n    $bottom: $b,\n    $left: $l,\n  );\n}\n\n@mixin padding-xy($x: null, $y: null) {\n  @include padding($x: $x, $y: $y);\n}\n\n///\n/// @alias padding-xy()\n///\n@mixin padding-axis($horizontal: null, $vertical: null) {\n  @include padding-xy($x: $horizontal, $y: $vertical);\n}\n\n@mixin padding-all($padding) {\n  @include padding($all: $padding);\n}\n\n///\n/// @alias padding-all()\n///\n@mixin padding-square($padding) {\n  @include padding-all($padding);\n}\n\n@mixin padding-none {\n  @include padding-all(0);\n}\n\n///\n/// @alias padding-none()\n///\n@mixin p-none {\n  @include padding-none;\n}\n\n///\n/// @alias p-none()\n///\n@mixin p-0 {\n  @include p-none;\n}\n\n@mixin padding-x($x: null) {\n  @include padding($x: $x);\n}\n\n///\n/// @alias padding-x()\n///\n@mixin px($x: null) {\n  @include padding-x($x);\n}\n\n@mixin px-none {\n  @include px(0);\n}\n\n///\n/// @alias px-none()\n///\n@mixin px-0 {\n  @include px-none;\n}\n\n@mixin padding-y($y: null) {\n  @include padding($y: $y);\n}\n\n///\n/// @alias padding-y()\n///\n@mixin py($y: null) {\n  @include padding-y($y);\n}\n\n@mixin py-none {\n  @include py(0);\n}\n\n///\n/// @alias py-none()\n///\n@mixin py-0 {\n  @include py-none;\n}\n\n@mixin padding-top($top: null) {\n  @include padding($top: $top);\n}\n\n///\n/// @alias padding-top()\n///\n@mixin pt($top: null) {\n  @include padding-top($top);\n}\n\n@mixin pt-none {\n  @include pt(0);\n}\n\n///\n/// @alias padding-top()\n///\n@mixin pt-0 {\n  @include pt-none;\n}\n\n@mixin padding-right($right: null) {\n  @include padding($right: $right);\n}\n\n///\n/// @alias padding-right()\n///\n@mixin pr($right: null) {\n  @include padding-right($right);\n}\n\n@mixin pr-none {\n  @include pr(0);\n}\n\n///\n/// @alias pr-none()\n///\n@mixin pr-0 {\n  @include pr-none;\n}\n\n@mixin padding-bottom($bottom: null) {\n  @include padding($bottom: $bottom);\n}\n\n///\n/// @alias padding-bottom()\n///\n@mixin pb($bottom: null) {\n  @include padding-bottom($bottom);\n}\n\n@mixin pb-none {\n  @include pb(0);\n}\n\n///\n/// @alias pb-none()\n///\n@mixin pb-0 {\n  @include pb-none;\n}\n\n@mixin padding-left($left: null) {\n  @include padding($left: $left);\n}\n\n///\n/// @alias padding-left()\n///\n@mixin pl($left: null) {\n  @include padding-left($left);\n}\n\n@mixin pl-none {\n  @include pl(0);\n}\n\n///\n/// @alias pl-none()\n///\n@mixin pl-0 {\n  @include pl-none;\n}\n","////\n/// @group position\n/// @access public\n/// @author Keith Choison <keith@tize.io>\n/// @since 0.1.0\n////\n\n@use 'sass:math';\n@use 'sass:meta';\n@use 'functions/list';\n\n///\n/// @access private\n///\n@mixin -inset(\n  $top: null,\n  $right: null,\n  $bottom: null,\n  $left: null,\n) {\n  @if $top {\n    top: $top;\n  }\n\n  @if $right {\n    right: $right;\n  }\n\n  @if $bottom {\n    bottom: $bottom;\n  }\n\n  @if $left {\n    left: $left;\n  }\n}\n\n@mixin inset(\n  $all: null,\n  $a: null,\n  $x: null,\n  $y: null,\n  $top: null,\n  $t: null,\n  $right: null,\n  $r: null,\n  $bottom: null,\n  $b: null,\n  $left: null,\n  $l: null,\n) {\n  @include -inset(\n    $top: if($top, $top, if($t, $t, if($y, $y, if($a, $a, $all)))),\n    $right: if($right, $right, if($r, $r, if($x, $x, if($a, $a, $all)))),\n    $bottom: if($bottom, $bottom, if($b, $b, if($y, $y, if($a, $a, $all)))),\n    $left: if($left, $left, if($l, $l, if($x, $x, if($a, $a, $all)))),\n  );\n}\n\n@mixin inset-all($all) {\n  @include inset($all: $all);\n}\n\n@mixin inset-none {\n  @include inset-all(0);\n}\n\n///\n/// @alias inset-none()\n///\n@mixin inset-0 {\n  @include inset-none;\n}\n\n@mixin inset-xy($x: null, $y: null) {\n  @include inset($x: $x, $y: $y);\n}\n\n@mixin inset-x($x) {\n  @include inset-xy($x: $x);\n}\n\n@mixin inset-x-none {\n  @include inset-x(0);\n}\n\n///\n/// @alias inset-x-none()\n///\n@mixin inset-x-0 {\n  @include inset-x-none;\n}\n\n@mixin inset-y($y) {\n  @include inset-xy($y: $y);\n}\n\n@mixin inset-y-none {\n  @include inset-y(0);\n}\n\n///\n/// @alias inset-y-none()\n///\n@mixin inset-y-0 {\n  @include inset-y-none;\n}\n\n@mixin top($top) {\n  @include inset($top: $top);\n}\n\n@mixin top-none {\n  @include top(0);\n}\n\n///\n/// @alias top-none()\n///\n@mixin top-0 {\n  @include top-none;\n}\n\n@mixin right($right) {\n  @include inset($right: $right);\n}\n\n@mixin right-none {\n  @include right(0);\n}\n\n///\n/// @alias right-none()\n///\n@mixin right-0 {\n  @include right-none;\n}\n\n@mixin bottom($bottom) {\n  @include inset($bottom: $bottom);\n}\n\n@mixin bottom-none {\n  @include bottom(0);\n}\n\n///\n/// @alias bottom-none()\n///\n@mixin bottom-0 {\n  @include bottom-none;\n}\n\n@mixin left($left) {\n  @include inset($left: $left);\n}\n\n@mixin left-none {\n  @include left(0);\n}\n\n///\n/// @alias left-none()\n///\n@mixin left-0 {\n  @include left-none;\n}\n\n@mixin unset-all {\n  @include inset-all(unset);\n}\n\n// translate\n\n@mixin translate(\n  $x: null,\n  $y: null,\n) {\n  @if meta.type-of($x) == 'number' or meta.type-of($y) == 'number' {\n    @if $x and $x != 0 and $y 